91	    private <M> Future<Void> execute(M message, ExecutionModel executionModel,
92	            Function<M, Uni<Void>> action, boolean terminateSession) {
93	        if (executionModel == ExecutionModel.NONE) {
94	            if (terminateSession) {
95	                // Just start and terminate the session context
96	                contextSupport.startSession();
97	                contextSupport.endSession();
98	            }
99	            return Future.succeededFuture();
100	        }
101	        Promise<Void> promise = Promise.promise();
102	        Context context = Vertx.currentContext();
103	        if (limiter != null) {
104	            PromiseComplete complete = limiter.newComplete(promise);
105	            limiter.run(context, new Runnable() {
106	                @Override
107	                public void run() {
108	                    doExecute(context, promise, message, executionModel, action, terminateSession, complete::complete,
109	                            complete::failure);
110	                }
111	            });
112	        } else {
113	            // No need to limit the concurrency
114	            doExecute(context, promise, message, executionModel, action, terminateSession, promise::complete, promise::fail);
115	        }
116	        return promise.future();
117	    }
