119	    private <M> void doExecute(Context context, Promise<Void> promise, M message, ExecutionModel executionModel,
120	            Function<M, Uni<Void>> action, boolean terminateSession, Runnable onComplete,
121	            Consumer<? super Throwable> onFailure) {
122	        Handler<Void> contextSupportEnd = executionModel.isBlocking() ? new Handler<Void>() {
123	
124	            @Override
125	            public void handle(Void event) {
126	                contextSupport.end(terminateSession);
127	            }
128	        } : null;
129	
130	        if (executionModel == ExecutionModel.VIRTUAL_THREAD) {
131	            VirtualThreadsRecorder.getCurrent().execute(new Runnable() {
132	                @Override
133	                public void run() {
134	                    Context context = Vertx.currentContext();
135	                    contextSupport.start();
136	                    action.apply(message).subscribe().with(
137	                            v -> {
138	                                context.runOnContext(contextSupportEnd);
139	                                onComplete.run();
140	                            },
141	                            t -> {
142	                                context.runOnContext(contextSupportEnd);
143	                                onFailure.accept(t);
144	                            });
145	                }
146	            });
147	        } else if (executionModel == ExecutionModel.WORKER_THREAD) {
